/* src/styles/6-components/bulletin.css */
/**
 * Bulletin — 소식 2단: 제목·마감 그림 열 + 탭 게시판 열 (블록 카탈로그 bulletin · design-intelligence §6-3 N2 + N1)
 *   왼쪽 열에 섹션 제목과 deadline(접수 중 항목의 남은 날수 그림), 오른쪽 열에 KRDS 탭 + post-list.
 *   게시판 첫 글은 대표 글로 키워 목록에 위계를 준다(N1).
 *   정본: src/blocks/bulletin/. MCP get_block("bulletin")
 *   <div class="container bulletin">
 *     <div class="bulletin__aside"><h2 class="bulletin__title">…</h2><div class="deadline">…</div></div>
 *     <div class="bulletin__board"><div class="tab">…</div></div>
 *   </div>
 * 레이어 밖에 둔다 — 탭·목록의 간격을 이 블록 안에서 조정한다.
 */
.bulletin {
  @apply grid gap-[4rem] laptop:gap-[6.4rem] laptop:[grid-template-columns:minmax(0,5fr)_minmax(0,7fr)];
}

/* 격자 칸이 내용 폭 때문에 넘치지 않게 */
.bulletin__aside,
.bulletin__board {
  @apply min-w-0;
}

/* KRDS heading-xlarge(mobile 2.8 / pc 4rem) */
.bulletin__title {
  @apply m-0 mb-[2.4rem] [font-family:var(--font-heading)] text-[2.8rem] font-semibold leading-[1.5] tracking-[0.1rem] text-[var(--color-text-bolder)] [word-break:keep-all] tablet:text-[4rem] laptop:mb-[4rem];
}

.bulletin__board .tab__list {
  @apply mb-[0.8rem];
}

/* 게시판 첫 글은 대표 글 — heading-medium으로 키운다 */
.bulletin__board .post-list__item:first-child {
  @apply py-[2.4rem];
}

.bulletin__board .post-list__item:first-child .post-list__link {
  @apply text-[2.2rem] font-bold leading-[1.5] tablet:text-[2.4rem];
}

/* src/styles/6-components/deadline.css */
/**
 * Deadline — 접수 중인 항목의 남은 날수 그림 (블록 카탈로그 bulletin의 부품 · design-intelligence §5-6·§6-3 N2)
 *   큰 숫자(남은 날수) + 제목 + 남은 기간 막대 + 마감일. 막대 길이는 --left(%)로 받고, 같은 정보를 글자로도 적는다.
 *   <div class="deadline">
 *     <div class="deadline__head"><h3 class="deadline__title">…</h3><p class="deadline__asof"><time datetime="…">…</time> 기준</p></div>
 *     <ol class="deadline__list" role="list">
 *       <li class="deadline__item">
 *         <p class="deadline__days"><strong class="deadline__count">8</strong>일 남음</p>
 *         <div class="deadline__body">
 *           <a class="deadline__link" href="…">…</a>
 *           <span class="deadline__bar" style="--left: 47%" aria-hidden="true"></span>
 *           <p class="deadline__meta"><time datetime="…">…</time> 마감</p>
 *         </div>
 *       </li>
 *     </ol>
 *   </div>
 * 레이어 밖에 둔다 — bulletin과 같은 층.
 */
.deadline {
  @apply p-[2.4rem] bg-[var(--color-point-5)] laptop:p-[3.2rem];
}

.deadline__head {
  @apply flex flex-wrap items-baseline justify-between gap-x-[1.6rem] gap-y-[0.4rem] mb-[2.4rem];
}

.deadline__title {
  @apply m-0 text-[1.9rem] font-bold leading-[1.5] text-[var(--color-text-bolder)] [word-break:keep-all];
}

.deadline__asof {
  @apply m-0 text-[1.5rem] leading-[1.5] text-[var(--color-point-60)] [font-variant-numeric:tabular-nums];
}

.deadline__list {
  @apply grid gap-[2.4rem] list-none m-0 p-0;
}

.deadline__item {
  @apply grid items-center gap-x-[2rem] [grid-template-columns:7.2rem_minmax(0,1fr)] tablet:[grid-template-columns:9.6rem_minmax(0,1fr)];
}

.deadline__days {
  @apply m-0 text-[1.5rem] leading-[1.5] text-[var(--color-point-60)] whitespace-nowrap;
}

/* KRDS display-small(4.4rem) — 숫자가 이 블록의 그림이다 */
.deadline__count {
  @apply block [font-family:var(--font-heading)] text-[4.4rem] font-semibold leading-[1.5] text-[var(--color-point-50)] [font-variant-numeric:tabular-nums];
}

.deadline__body {
  @apply min-w-0;
}

.deadline__link {
  @apply text-[1.9rem] font-bold leading-[1.5] text-[var(--color-text-bolder)] no-underline [word-break:keep-all] [text-underline-offset:0.4rem] hover:underline;
}

/* 남은 기간 막대 — 기준일부터 마감까지. 가장 늦은 마감이 100% */
.deadline__bar {
  @apply relative block h-[0.4rem] mt-[1.2rem] bg-[var(--color-point-20)];
}

.deadline__bar::after {
  @apply content-[''] absolute inset-y-0 start-0 w-[var(--left)] bg-[var(--color-point-50)];
}

.deadline__meta {
  @apply m-0 mt-[0.8rem] text-[1.5rem] leading-[1.5] text-[var(--color-text-subtle)] [font-variant-numeric:tabular-nums];
}

/* src/styles/6-components/post-list.css */
/**
 * Post List — 게시판 최신 글 목록: 제목 + 날짜 (블록 카탈로그 bulletin의 부품 · KS-04 목록 자리)
 *   제목은 768px 이상에서 두 줄까지 보이고(좁은 화면은 전부 보인다) 날짜는 오른쪽 열에 자릿수를 맞춘다.
 *   <ul class="post-list" role="list">
 *     <li class="post-list__item">
 *       <a class="post-list__link" href="…">제목</a>
 *       <time class="post-list__date" datetime="2026-10-15">2026.10.15</time>
 *     </li>
 *   </ul>
 * 레이어 밖에 둔다 — bulletin이 첫 글의 크기를 바꾼다.
 */
.post-list {
  @apply list-none m-0 p-0 border-t border-[var(--color-border)];
}

.post-list__item {
  @apply flex flex-col gap-[0.2rem] py-[0.4rem] border-b border-[var(--color-border-light)] tablet:flex-row tablet:items-baseline tablet:gap-[2.4rem] tablet:py-[1.2rem];
}

.post-list__link {
  @apply flex flex-1 items-center min-w-0 min-h-[4.4rem] tablet:min-h-0 text-[1.7rem] leading-[1.5] text-[var(--color-text)] no-underline [word-break:keep-all] tablet:overflow-hidden tablet:[display:-webkit-box] tablet:[-webkit-box-orient:vertical] tablet:[-webkit-line-clamp:2] [transition:color_0.15s_ease-in-out];
}

.post-list__link:visited {
  @apply text-[var(--color-text)];
}

.post-list__link:hover {
  @apply text-[var(--color-link-hover)] underline;
}

.post-list__date {
  @apply shrink-0 text-[1.5rem] leading-[1.5] text-[var(--color-text-subtle)] [font-variant-numeric:tabular-nums];
}

/* src/styles/6-components/more-link.css */
/**
 * More Link — 「<게시판명> 전체 보기」 링크 (블록 카탈로그 bulletin의 부품)
 *   이름에 목적지를 적는다 — 「더보기」만 쓰지 않는다(R-30).
 *   <a class="more-link" href="…">공지사항 전체 보기
 *     <svg class="icon icon--xsmall" aria-hidden="true"><use href="/assets/icons/sprite.svg#chevron-right"></use></svg>
 *   </a>
 * 레이어 밖에 둔다 — bulletin과 같은 층.
 */
.more-link {
  @apply inline-flex items-center gap-[0.4rem] min-h-[4.4rem] mt-[0.8rem] text-[1.7rem] font-bold leading-[1.5] text-[var(--color-text)] no-underline [transition:color_0.15s_ease-in-out];
}

.more-link:visited {
  @apply text-[var(--color-text)];
}

.more-link:hover {
  @apply text-[var(--color-link-hover)] underline;
}
